table inet fw4 {
	chain input {
		type filter hook input priority filter; policy drop;
		iif "lo" accept comment "!fw4: Accept traffic from loopback"
		ct state vmap { established : accept, related : accept } comment "!fw4: Handle inbound flows"
		tcp flags & (fin | syn | rst | ack) == syn jump syn_flood comment "!fw4: Rate limit TCP syn packets"
		iifname "br-lan" jump input_lan comment "!fw4: Handle lan IPv4/IPv6 input traffic"
		iifname "eth1" jump input_lan_a comment "!fw4: Handle lan_a IPv4/IPv6 input traffic"
		iifname "eth2" jump input_lan_b comment "!fw4: Handle lan_b IPv4/IPv6 input traffic"
		jump handle_reject
	}

	chain forward {
		type filter hook forward priority filter; policy drop;
		ct state vmap { established : accept, related : accept } comment "!fw4: Handle forwarded flows"
		iifname "br-lan" jump forward_lan comment "!fw4: Handle lan IPv4/IPv6 forward traffic"
		iifname "eth1" jump forward_lan_a comment "!fw4: Handle lan_a IPv4/IPv6 forward traffic"
		iifname "eth2" jump forward_lan_b comment "!fw4: Handle lan_b IPv4/IPv6 forward traffic"
		jump handle_reject
	}

	chain output {
		type filter hook output priority filter; policy accept;
		oif "lo" accept comment "!fw4: Accept traffic towards loopback"
		ct state vmap { established : accept, related : accept } comment "!fw4: Handle outbound flows"
		oifname "br-lan" jump output_lan comment "!fw4: Handle lan IPv4/IPv6 output traffic"
		oifname "eth1" jump output_lan_a comment "!fw4: Handle lan_a IPv4/IPv6 output traffic"
		oifname "eth2" jump output_lan_b comment "!fw4: Handle lan_b IPv4/IPv6 output traffic"
	}

	chain prerouting {
		type filter hook prerouting priority filter; policy accept;
		iifname "br-lan" jump helper_lan comment "!fw4: Handle lan IPv4/IPv6 helper assignment"
		iifname "eth1" jump helper_lan_a comment "!fw4: Handle lan_a IPv4/IPv6 helper assignment"
		iifname "eth2" jump helper_lan_b comment "!fw4: Handle lan_b IPv4/IPv6 helper assignment"
	}

	chain handle_reject {
		meta l4proto tcp reject with tcp reset comment "!fw4: Reject TCP traffic"
		reject comment "!fw4: Reject any other traffic"
	}

	chain syn_flood {
		limit rate 25/second burst 50 packets return comment "!fw4: Accept SYN packets below rate-limit"
		drop comment "!fw4: Drop excess packets"
	}

	chain input_lan {
		jump accept_from_lan
	}

	chain output_lan {
		jump accept_to_lan
	}

	chain forward_lan {
		jump accept_to_wan comment "!fw4: Accept lan to wan forwarding"
		jump accept_to_lan
	}

	chain helper_lan {
	}

	chain accept_from_lan {
		iifname "br-lan" counter packets 1 bytes 60 accept comment "!fw4: accept lan IPv4/IPv6 traffic"
	}

	chain accept_to_lan {
		oifname "br-lan" counter packets 1 bytes 160 accept comment "!fw4: accept lan IPv4/IPv6 traffic"
	}

	chain input_wan {
		meta nfproto ipv4 udp dport 68 counter packets 0 bytes 0 accept comment "!fw4: Allow-DHCP-Renew"
		icmp type echo-request counter packets 0 bytes 0 accept comment "!fw4: Allow-Ping"
		meta nfproto ipv4 meta l4proto igmp counter packets 0 bytes 0 accept comment "!fw4: Allow-IGMP"
		meta nfproto ipv6 udp dport 546 counter packets 0 bytes 0 accept comment "!fw4: Allow-DHCPv6"
		ip6 saddr fe80::/10 icmpv6 type . icmpv6 code { mld-listener-query . 0, mld-listener-report . 0, mld-listener-done . 0, mld2-listener-report . 0 } counter packets 0 bytes 0 accept comment "!fw4: Allow-MLD"
		icmpv6 type { destination-unreachable, time-exceeded, echo-request, echo-reply, nd-router-solicit, nd-router-advert } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Input"
		icmpv6 type . icmpv6 code { packet-too-big . 0, parameter-problem . 0, nd-neighbor-solicit . 0, nd-neighbor-advert . 0, parameter-problem . 1 } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Input"
		jump reject_from_wan
	}

	chain output_wan {
		jump accept_to_wan
	}

	chain forward_wan {
		icmpv6 type { destination-unreachable, time-exceeded, echo-request, echo-reply } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Forward"
		icmpv6 type . icmpv6 code { packet-too-big . 0, parameter-problem . 0, parameter-problem . 1 } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Forward"
		meta l4proto esp counter packets 0 bytes 0 jump accept_to_lan comment "!fw4: Allow-IPSec-ESP"
		udp dport 500 counter packets 0 bytes 0 jump accept_to_lan comment "!fw4: Allow-ISAKMP"
		jump drop_to_wan
	}

	chain accept_to_wan {
	}

	chain reject_from_wan {
	}

	chain drop_to_wan {
	}

	chain dstnat {
		type nat hook prerouting priority dstnat; policy accept;
	}

	chain srcnat {
		type nat hook postrouting priority srcnat; policy accept;
	}

	chain srcnat_wan {
		meta nfproto ipv4 masquerade comment "!fw4: Masquerade IPv4 wan traffic"
	}

	chain raw_prerouting {
		type filter hook prerouting priority raw; policy accept;
	}

	chain raw_output {
		type filter hook output priority raw; policy accept;
	}

	chain mangle_prerouting {
		type filter hook prerouting priority mangle; policy accept;
	}

	chain mangle_postrouting {
		type filter hook postrouting priority mangle; policy accept;
	}

	chain mangle_input {
		type filter hook input priority mangle; policy accept;
	}

	chain mangle_output {
		type route hook output priority mangle; policy accept;
	}

	chain mangle_forward {
		type filter hook forward priority mangle; policy accept;
	}

	chain input_lan_a {
		jump accept_from_lan_a
	}

	chain output_lan_a {
		jump accept_to_lan_a
	}

	chain forward_lan_a {
		tcp dport 5432 counter packets 1 bytes 60 jump accept_to_lan_b comment "!fw4: Allow-lanA-to-lanB-postgres"
		jump accept_to_lan_b comment "!fw4: Accept lan_a to lan_b forwarding"
		jump reject_to_lan_a
	}

	chain helper_lan_a {
	}

	chain accept_from_lan_a {
		iifname "eth1" counter packets 1 bytes 48 accept comment "!fw4: accept lan_a IPv4/IPv6 traffic"
	}

	chain accept_to_lan_a {
		oifname "eth1" counter packets 0 bytes 0 accept comment "!fw4: accept lan_a IPv4/IPv6 traffic"
	}

	chain reject_to_lan_a {
		oifname "eth1" counter packets 0 bytes 0 jump handle_reject comment "!fw4: reject lan_a IPv4/IPv6 traffic"
	}

	chain input_lan_b {
		jump accept_from_lan_b
	}

	chain output_lan_b {
		jump accept_to_lan_b
	}

	chain forward_lan_b {
		jump accept_to_lan_a comment "!fw4: Accept lan_b to lan_a forwarding"
		jump reject_to_lan_b
	}

	chain helper_lan_b {
	}

	chain accept_from_lan_b {
		iifname "eth2" counter packets 1 bytes 48 accept comment "!fw4: accept lan_b IPv4/IPv6 traffic"
	}

	chain accept_to_lan_b {
		oifname "eth2" counter packets 2 bytes 120 accept comment "!fw4: accept lan_b IPv4/IPv6 traffic"
	}

	chain reject_to_lan_b {
		oifname "eth2" counter packets 0 bytes 0 jump handle_reject comment "!fw4: reject lan_b IPv4/IPv6 traffic"
	}
}

table inet fw4 {
	chain forward_lan_a {
		tcp dport 5432 counter packets 0 bytes 0 jump accept_to_lan_b comment "!fw4: Allow-lanA-to-lanB-postgres"
		jump reject_to_lan_a
	}
}
---
table inet fw4 {
	chain forward_lan_b {
		jump reject_to_lan_b
	}
}

table inet fw4 {
	chain forward_lan_a {
		tcp dport 5432 counter packets 1 bytes 60 jump accept_to_lan_b comment "!fw4: Allow-lanA-to-lanB-postgres"
		jump reject_to_lan_a
	}
}
---
table inet fw4 {
	chain accept_to_lan_b {
		oifname "eth2" counter packets 1 bytes 60 accept comment "!fw4: accept lan_b IPv4/IPv6 traffic"
	}
}
